<script setup lang="ts">
import{computed,onMounted,onUnmounted,reactive,ref,watch}from'vue';
import{edgeSize,initialEdgeLevels,validateEdgeSettings}from'../../../packages/comp-bridge/edge-refinement.mjs';
import{parityMessages}from'./parity-labels';
import{localizedMessages}from'../../../packages/locales';
import type{Language,ViewerProject,LayerRow,OpenResult}from'./types';
const props=defineProps<{language:Language;project:ViewerProject;layer:LayerRow;commit:(op:Record<string,unknown>,owner:{id:string;revision:string})=>Promise<OpenResult>}>(),emit=defineEmits(['close','running']),t=computed(()=>parityMessages[props.language]),owner={id:props.project.id,revision:props.project.revision};
const canvas=ref<HTMLCanvasElement>(),viewport=ref<HTMLDivElement>(),busy=ref(true),computing=ref(true),working=ref(false),applying=ref(false),error=ref(''),canUndo=ref(false),canRedo=ref(false),mode=ref('refine'),background=ref('checker'),diameter=ref(50),strength=ref(.6),width=ref(1),height=ref(1),sourceWidth=ref(1),settings=reactive({feather:0,shift:0,contrast:0,decontaminate:0,copy:true}),fitting=ref(true),zoom=ref(1),area=reactive({width:700,height:400});
const copyBlocked=props.project.analysis.rows.some(row=>row.maskSourceID?.toUpperCase()===props.layer.id.toUpperCase());if(copyBlocked)settings.copy=false;
const factor=computed(()=>fitting.value?Math.max(.01,Math.min((area.width-20)/width.value,(area.height-20)/height.value)):zoom.value),percent=computed(()=>Math.round(factor.value*width.value/sourceWidth.value*100)),valid=computed(()=>{try{validateEdgeSettings({...settings});return Number.isFinite(diameter.value)&&diameter.value>=2&&diameter.value<=1000&&Number.isFinite(strength.value)&&strength.value>=0&&strength.value<=1&&(!copyBlocked||!settings.copy&&!settings.decontaminate);}catch{return false;}});
let worker:Worker|undefined,observer:ResizeObserver|undefined,live=true,stroke=false,ending=false,queued:number[]|undefined,frame=0,inFlight=false,pending=0,configureNeeded=false,timer:ReturnType<typeof setTimeout>|undefined,configureTimer:ReturnType<typeof setTimeout>|undefined;
const plain=()=>({...settings});
function watchdog(){clearTimeout(timer);if(!inFlight)return;timer=setTimeout(()=>{worker?.terminate();error.value=t.value.failed;applying.value=false;busy.value=false;computing.value=false;working.value=false;},30000);}
function send(message:Record<string,unknown>){if(!worker||!live)return;pending++;inFlight=true;computing.value=true;watchdog();worker.postMessage(message);}
function draw(image:any){const target=canvas.value;if(!target)return;target.width=image.width;target.height=image.height;target.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.width,image.height),0,0);}
function configure(){if(!worker||busy.value||working.value||applying.value||!valid.value){computing.value=inFlight;return;}if(inFlight){configureNeeded=true;computing.value=true;return;}configureNeeded=false;send({action:'configure',settings:plain(),maskOnly:background.value==='mask'});}
watch([settings,background],()=>{clearTimeout(configureTimer);computing.value=true;configureTimer=setTimeout(()=>{configureTimer=undefined;configure();},60);},{deep:true});
function point(event:PointerEvent){const bounds=canvas.value!.getBoundingClientRect();return[(event.clientX-bounds.left)*width.value/bounds.width,(event.clientY-bounds.top)*height.value/bounds.height];}
function flush(){frame=0;if(inFlight||busy.value||!worker)return;if(queued){const at=[...queued];queued=undefined;send({action:'stroke',point:at,settings:plain(),maskOnly:background.value==='mask',brush:{mode:mode.value,diameter:diameter.value,strength:strength.value}});}else if(ending){ending=false;send({action:'end'});}}
function start(event:PointerEvent){if(busy.value||working.value||applying.value||!valid.value||event.button!==0)return;clearTimeout(configureTimer);configureTimer=undefined;configureNeeded=false;canvas.value!.focus({preventScroll:true});canvas.value!.setPointerCapture(event.pointerId);stroke=true;working.value=true;queued=point(event);flush();event.preventDefault();}
function move(event:PointerEvent){if(!stroke)return;queued=point(event);if(!frame)frame=requestAnimationFrame(flush);}
function end(){if(!stroke)return;stroke=false;ending=true;flush();}
function history(action:string){if(!busy.value&&!working.value&&!applying.value&&!inFlight&&!(document.activeElement instanceof HTMLElement&&document.activeElement.closest('input,textarea,select,[contenteditable]'))&&(action==='undo'?canUndo.value:canRedo.value))send({action});}
const stopUndo=window.editor.onCommand('undo',()=>history('undo')),stopRedo=window.editor.onCommand('redo',()=>history('redo'));
function scale(amount:number){if(busy.value||working.value)return;zoom.value=Math.max(.01,Math.min(20*sourceWidth.value/width.value,factor.value*amount));fitting.value=false;}
function close(){if(!applying.value)emit('close');}
function enter(event:KeyboardEvent){if(!event.isComposing&&!(event.target instanceof HTMLElement&&event.target.closest('select,button'))){event.preventDefault();event.stopPropagation();apply();}}
function apply(){if(busy.value||working.value||computing.value||inFlight||applying.value||!valid.value)return;clearTimeout(configureTimer);configureTimer=undefined;applying.value=true;send({action:'save'});}
async function commit(record:Record<string,unknown>){try{const result=await props.commit({kind:'refineEdges',id:props.layer.id,mask:record,settings:plain(),name:props.layer.name+' — '+t.value.refinedSuffix},owner);if(result.project)emit('close');else error.value=(localizedMessages(props.language,'windows').errors as Record<string,string>)[result.error??'invalid']??t.value.failed;}catch{error.value=t.value.failed;}finally{applying.value=false;}}
async function bitmap(url:string){const response=await fetch(url);if(!response.ok)throw new Error('asset');return createImageBitmap(await response.blob());}
onMounted(async()=>{emit('running',true);observer=new ResizeObserver(entries=>{area.width=entries[0].contentRect.width;area.height=entries[0].contentRect.height;});observer.observe(viewport.value!);let source:ImageBitmap|undefined,maskImage:ImageBitmap|undefined;
  try{const images=await Promise.allSettled([bitmap(props.project.urls['images/'+props.layer.imageFile]),props.layer.maskFile?bitmap(props.project.urls['images/'+props.layer.maskFile]):undefined]);if(images.some(result=>result.status==='rejected')){for(const result of images)if(result.status==='fulfilled')result.value?.close();throw new Error('asset');}source=(images[0] as PromiseFulfilledResult<ImageBitmap>).value;maskImage=(images[1] as PromiseFulfilledResult<ImageBitmap|undefined>).value;if(!live)return;sourceWidth.value=source.width;const size=edgeSize(source.width,source.height);width.value=size.width;height.value=size.height;const surface=document.createElement('canvas');surface.width=size.width;surface.height=size.height;const context=surface.getContext('2d')!;context.imageSmoothingQuality='high';context.drawImage(source,0,0,size.width,size.height);const image=context.getImageData(0,0,size.width,size.height);surface.width=surface.height=1;let mask:any;
    if(maskImage){surface.width=maskImage.width;surface.height=maskImage.height;context.drawImage(maskImage,0,0);const data=context.getImageData(0,0,surface.width,surface.height);mask={width:data.width,height:data.height,data:data.data};surface.width=surface.height=1;}
    const initial=initialEdgeLevels(source.width,source.height,props.layer,mask,props.project.selection),task=worker=new Worker(new URL('./edge-refinement-worker.ts',import.meta.url),{type:'module'});task.onmessage=event=>{if(!live)return;pending=Math.max(0,pending-1);inFlight=pending>0;computing.value=inFlight||configureTimer!==undefined||configureNeeded;watchdog();if(event.data.error){error.value=t.value.failed;applying.value=false;busy.value=false;working.value=false;return;}if(event.data.saved){void commit(event.data.saved);return;}draw(event.data.image);canUndo.value=event.data.canUndo;canRedo.value=event.data.canRedo;busy.value=false;if(queued||ending)flush();else if(!stroke)working.value=false;if(configureNeeded&&!working.value&&!inFlight)configure();};task.onerror=()=>{error.value=t.value.failed;applying.value=false;busy.value=false;working.value=false;};send({action:'init',source:{width:image.width,height:image.height,data:image.data},sourceWidth:source.width,levels:initial.levels,settings:plain()});
  }catch{error.value=t.value.failed;busy.value=false;}finally{source?.close();maskImage?.close();}});
onUnmounted(()=>{live=false;observer?.disconnect();worker?.terminate();clearTimeout(timer);clearTimeout(configureTimer);cancelAnimationFrame(frame);stopUndo();stopRedo();emit('running',false);});
</script>
<template><div class="modal-shade" @keydown.esc.stop.prevent="close" @click.self="close"><section class="dialog edge-dialog" role="dialog" @keydown.enter="enter" aria-modal="true" :aria-label="t.refineEdges"><h2>{{t.refineEdges}}</h2><p>{{t.edgeHint}}</p><p v-if="error" role="alert">{{error}}</p><div class="edge-layout"><div><div ref="viewport" class="edge-viewport" data-testid="edge-viewport" :class="'edge-'+background"><canvas ref="canvas" data-testid="edge-canvas" tabindex="0" :aria-label="t.refineEdges" :style="{width:width*factor+'px',height:height*factor+'px'}" @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="end" @lostpointercapture="end"></canvas></div><div class="button-row"><button :disabled="busy||working" @click="fitting=true">{{t.fit}}</button><button :disabled="busy||working" @click="zoom=sourceWidth/width;fitting=false">100%</button><button :disabled="busy||working" @click="scale(.8)">−</button><span>{{percent}}%</span><button :disabled="busy||working" @click="scale(1.25)">+</button></div></div><fieldset :disabled="busy||working||applying"><label>{{t.tool}}<select v-model="mode" data-testid="edge-brush"><option value="refine">{{t.refineEdges}}</option><option value="reveal">{{t.edgeReveal}}</option><option value="hide">{{t.edgeHide}}</option></select></label><label>{{t.diameter}}<input v-model.number="diameter" data-testid="edge-diameter" type="number" min="2" max="1000"></label><label>{{t.strength}}<input v-model.number="strength" data-testid="edge-strength" type="number" min="0" max="1" step=".01"></label><label>{{t.edgeView}}<select v-model="background" data-testid="edge-background"><option value="checker">{{t.edgeChecker}}</option><option value="black">{{t.edgeBlack}}</option><option value="white">{{t.edgeWhite}}</option><option value="mask">{{t.rangeMask}}</option></select></label><label>{{t.edgeFeather}}<input v-model.number="settings.feather" data-testid="edge-feather" type="number" min="0" max="100" step=".1"></label><label>{{t.edgeShift}}<input v-model.number="settings.shift" data-testid="edge-shift" type="number" min="-100" max="100" step=".1"></label><label>{{t.edgeContrast}}<input v-model.number="settings.contrast" data-testid="edge-contrast" type="number" min="0" max="100" step=".1"></label><label>{{t.edgeDecontaminate}}<input v-model.number="settings.decontaminate" data-testid="edge-decontaminate" type="number" min="0" max="100" step=".1" :disabled="copyBlocked"></label><label><input v-model="settings.copy" data-testid="edge-copy" type="checkbox" :disabled="copyBlocked||settings.decontaminate>0">{{t.createCopy}}</label><p>{{copyBlocked?t.edgeClipNote:t.edgeCopyNote}}</p></fieldset></div><div class="button-row dialog-actions"><button :disabled="!canUndo||working||busy||applying" data-testid="edge-undo" @click="history('undo')">{{t.undo}}</button><button :disabled="!canRedo||working||busy||applying" data-testid="edge-redo" @click="history('redo')">{{t.redo}}</button><span class="spacer"></span><button :disabled="applying" @click="close">{{t.cancel}}</button><button class="primary" data-testid="edge-apply" :disabled="busy||working||computing||applying||!valid||!!error" @click="apply">{{applying?t.loading:t.apply}}</button></div></section></div></template>
<style scoped>.edge-dialog{width:min(1100px,96vw);max-height:94vh;overflow:auto}.edge-layout{display:grid;grid-template-columns:minmax(0,1fr) 245px;gap:16px}.edge-viewport{height:52vh;overflow:auto;background:repeating-conic-gradient(#555 0 25%,#888 0 50%) 0/16px 16px}.edge-black{background:#000}.edge-white{background:#fff}.edge-mask{background:#888}.edge-viewport canvas{display:block;max-width:none;margin:auto;touch-action:none;cursor:crosshair}.edge-layout fieldset{border:0;padding:0;max-height:58vh;overflow:auto}.edge-layout fieldset>label{display:flex;justify-content:space-between;gap:8px;margin:8px 0}.edge-layout input[type=number]{width:80px}.spacer{flex:1}@media(max-width:900px){.edge-layout{grid-template-columns:minmax(0,1fr) 210px}}</style>
